  status=new TextView(this);status.setText(captureJournal.historicalSummary()==null?"Idle — explicit permission and capture required":"Idle — historical completed capture available; no current capture");layout.addView(status);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(layout);setContentView(scroll);
