 private void show(String value){ui.post(()->{if(status!=null)status.setText(value);});}
 private boolean permissionExists(String name){try{getPackageManager().getPermissionInfo(name,0);return true;}catch(PackageManager.NameNotFoundException e){return false;}}
 private boolean permitted(){return checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED&&(!permissionExists(HEADSET)||checkSelfPermission(HEADSET)==PackageManager.PERMISSION_GRANTED);}
 private void requestAndEnumerate(){if(capturing)return;List<String> names=new ArrayList<>();names.add(Manifest.permission.CAMERA);if(permissionExists(HEADSET))names.add(HEADSET);if(permitted())worker.post(this::enumerate);else requestPermissions(names.toArray(new String[0]),7);}
 @Override public void onRequestPermissionsResult(int code,String[] names,int[] grants){super.onRequestPermissionsResult(code,names,grants);if(code==7){if(permitted())worker.post(this::enumerate);else show("Camera permission denied; no camera opened");}}
 private static Object value(Object v)throws JSONException {if(v==null)return JSONObject.NULL;if(v.getClass().isArray())return new JSONArray(v);if(v instanceof Number||v instanceof Boolean||v instanceof String)return v;return v.toString();}
 private <T> void characteristic(JSONObject out,CameraCharacteristics c,CameraCharacteristics.Key<T> key){try{out.put(key.getName(),value(c.get(key)));}catch(Exception e){try{out.put(key.getName()+"Error",e.getClass().getSimpleName());}catch(JSONException ignored){}}}
 private JSONArray inventory()throws Exception {
  JSONArray list=new JSONArray();for(String id:manager.getCameraIdList()){CameraCharacteristics c=manager.getCameraCharacteristics(id);JSONObject o=new JSONObject();o.put("cameraId",id);characteristic(o,c,SOURCE);characteristic(o,c,POSITION);characteristic(o,c,CameraCharacteristics.LENS_INTRINSIC_CALIBRATION);characteristic(o,c,CameraCharacteristics.LENS_DISTORTION);characteristic(o,c,CameraCharacteristics.LENS_POSE_ROTATION);characteristic(o,c,CameraCharacteristics.LENS_POSE_TRANSLATION);characteristic(o,c,CameraCharacteristics.LENS_POSE_REFERENCE);characteristic(o,c,CameraCharacteristics.SENSOR_INFO_TIMESTAMP_SOURCE);characteristic(o,c,CameraCharacteristics.SENSOR_INFO_ACTIVE_ARRAY_SIZE);characteristic(o,c,CameraCharacteristics.SENSOR_ORIENTATION);characteristic(o,c,CameraCharacteristics.INFO_SUPPORTED_HARDWARE_LEVEL);
   JSONArray vendorKeys=new JSONArray();for(CameraCharacteristics.Key<?> k:c.getKeys())if(k.getName().startsWith("com.meta.extra_metadata."))vendorKeys.put(k.getName());o.put("metaVendorKeyNames",vendorKeys);
   JSONArray sizes=new JSONArray();StreamConfigurationMap map=c.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP);Size[] supported=map==null?null:map.getOutputSizes(ImageFormat.YUV_420_888);if(supported!=null)for(Size z:supported)sizes.put(new JSONArray(new int[]{z.getWidth(),z.getHeight()}));o.put("yuv420Sizes",sizes);list.put(o);
  }return list;
 }
 private void enumerate(){try{receipt=new JSONObject();receipt.put("schemaVersion",1);receipt.put("phase","enumerated");receipt.put("apiLevel",Build.VERSION.SDK_INT);receipt.put("model",Build.MODEL);receipt.put("cameraPermission",checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED);receipt.put("headsetPermissionDeclaredByOS",permissionExists(HEADSET));receipt.put("headsetPermissionGranted",checkSelfPermission(HEADSET)==PackageManager.PERMISSION_GRANTED);receipt.put("cameras",inventory());JSONArray concurrent=new JSONArray();if(Build.VERSION.SDK_INT>=30)for(Set<String> ids:manager.getConcurrentCameraIds())concurrent.put(new JSONArray(ids));receipt.put("concurrentCameraIdSets",concurrent);receipt.put("roomFramesPersisted",false);receipt.put("poseEstablished",false);captureJournal.inventory(receipt.toString());show("Enumerated "+receipt.getJSONArray("cameras").length()+" cameras; no camera opened");}catch(Exception e){fail("enumerate",e);}}
 private boolean live(long token){return foreground&&capturing&&generation==token;}
 private void begin(long token){if(!live(token))return;closeResources();try{
  enumerate();String selected=null;Size size=null;
  for(String id:manager.getCameraIdList()){CameraCharacteristics c=manager.getCameraCharacteristics(id);Integer source;try{source=c.get(SOURCE);}catch(IllegalArgumentException e){continue;}if(source==null||source!=0)continue;
   StreamConfigurationMap map=c.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP);Size[] sizes=map==null?null:map.getOutputSizes(ImageFormat.YUV_420_888);if(sizes==null)continue;
   for(Size s:sizes)if((!configuredHighResolution||(s.getWidth()==1280&&s.getHeight()==960))&&s.getWidth()<=1280&&s.getHeight()<=960&&(size==null||(configuredMarkerId==null&&!configuredHighResolution?(long)s.getWidth()*s.getHeight()<(long)size.getWidth()*size.getHeight():(long)s.getWidth()*s.getHeight()>(long)size.getWidth()*size.getHeight()))){selected=id;size=s;}
   if(selected!=null)break;
  }
  if(selected==null||size==null)throw new IllegalStateException("No tagged public passthrough YUV camera within analysis bounds");
  captureCharacteristics=manager.getCameraCharacteristics(selected);markerEstimator=configuredMarkerId==null?null:new MarkerPoseEstimator(configuredMarkerId,configuredMarkerSide);matchedResults.clear();
  receipt.put("unmodifiedHighResolutionObservability",configuredHighResolution);receipt.put("requestedActionCueIsNotPhysicalVerification",true);receipt.put("analysisRateLimitHz",configuredHighResolution?2:5);receipt.put("penIdentityEstablished",false);receipt.put("clockComparisonScope","Raw paired clock observations only; no UNKNOWN timestamp domain conversion");receipt.put("optionalMarkerMode",configuredMarkerId!=null);receipt.put("markerMaxImageAgeMs",500);receipt.put("markerMaxFutureMs",5);receipt.put("markerRequiredTimestampSource","REALTIME");receipt.put("configuredMarkerId",configuredMarkerId==null?JSONObject.NULL:configuredMarkerId);receipt.put("measuredBlackSideMeters",configuredMarkerId==null?JSONObject.NULL:configuredMarkerSide);receipt.put("currentMarkerPose",JSONObject.NULL);receipt.put("worldPoseEstablished",false);receipt.put("musePoseEstablished",false);
  frames=new JSONArray();requestedPhaseChanges=new JSONArray();lastRequestedPhase="";received=processed=0;latestResult=new JSONObject();startNs=SystemClock.elapsedRealtimeNanos();receipt.put("captureId",captureJournal.begin(startNs));lastProcessedNs=0;receipt.put("selectedCameraId",selected);receipt.put("width",size.getWidth());receipt.put("height",size.getHeight());receipt.put("startedWallTimeMs",System.currentTimeMillis());receipt.put("startElapsedRealtimeNanos",startNs);receipt.put("durationLimitMs",20000);receipt.put("threshold",BrightBlobDetector.THRESHOLD);receipt.put("sampleStep",BrightBlobDetector.STEP);receipt.put("maxRetainedFrames",configuredHighResolution?40:100);receipt.put("phase","opening");persist();
  reader=ImageReader.newInstance(size.getWidth(),size.getHeight(),ImageFormat.YUV_420_888,2);reader.setOnImageAvailableListener(r->analyze(r,token),worker);ui.postDelayed(deadline,20000);if(configuredHighResolution){cueGeneration=token;ui.post(trialCue);}if(markerEstimator!=null)ui.postDelayed(poseFreshness,500);
  pendingOpens++;try{manager.openCamera(selected,new CameraDevice.StateCallback(){private boolean pending=true;private void releasePending(){if(pending){pending=false;pendingOpens--;}maybeQuitWorker();}public void onOpened(CameraDevice d){if(!live(token)){d.close();releasePending();return;}camera=d;releasePending();try{d.createCaptureSession(Collections.singletonList(reader.getSurface()),new CameraCaptureSession.StateCallback(){public void onConfigured(CameraCaptureSession s){if(!live(token)){s.close();return;}session=s;try{CaptureRequest.Builder q=d.createCaptureRequest(CameraDevice.TEMPLATE_PREVIEW);q.addTarget(reader.getSurface());if(markerEstimator!=null){q.set(CaptureRequest.DISTORTION_CORRECTION_MODE,CaptureRequest.DISTORTION_CORRECTION_MODE_OFF);q.set(CaptureRequest.CONTROL_VIDEO_STABILIZATION_MODE,CaptureRequest.CONTROL_VIDEO_STABILIZATION_MODE_OFF);q.set(CaptureRequest.LENS_OPTICAL_STABILIZATION_MODE,CaptureRequest.LENS_OPTICAL_STABILIZATION_MODE_OFF);if(Build.VERSION.SDK_INT>=30)q.set(CaptureRequest.CONTROL_ZOOM_RATIO,1f);if(Build.VERSION.SDK_INT>=31)q.set(CaptureRequest.SCALER_ROTATE_AND_CROP,CaptureRequest.SCALER_ROTATE_AND_CROP_NONE);}s.setRepeatingRequest(q.build(),new CameraCaptureSession.CaptureCallback(){@Override public void onCaptureCompleted(CameraCaptureSession ss,CaptureRequest request,TotalCaptureResult result){if(live(token))recordResult(result);}},worker);receipt.put("phase","capturing");persist();show("Capturing bounded bright-blob statistics; no images saved");}catch(Exception e){fail("repeat",e);stop("capture-error");}}public void onConfigureFailed(CameraCaptureSession s){s.close();if(live(token)){fail("configure",new IllegalStateException("Session configuration failed"));stop("configure-error");}}},worker);}catch(Exception e){fail("session",e);stop("session-error");}}public void onDisconnected(CameraDevice d){d.close();releasePending();if(live(token))stop("camera-disconnected");}public void onError(CameraDevice d,int error){d.close();releasePending();if(live(token)){fail("camera",new IllegalStateException("Camera error "+error));stop("camera-error");}}},worker);}catch(Exception e){pendingOpens--;throw e;}
 }catch(Exception e){fail("open",e);stop("open-error");}}
 private static JSONObject resultSummary(TotalCaptureResult result)throws JSONException {return new JSONObject().put("sensorTimestampNanos",value(result.get(CaptureResult.SENSOR_TIMESTAMP))).put("exposureNanos",value(result.get(CaptureResult.SENSOR_EXPOSURE_TIME))).put("sensitivity",value(result.get(CaptureResult.SENSOR_SENSITIVITY))).put("frameDurationNanos",value(result.get(CaptureResult.SENSOR_FRAME_DURATION))).put("cropRegion",value(result.get(CaptureResult.SCALER_CROP_REGION)));}
 private static JSONArray componentSummary(List<LumaObservability.Blob> blobs)throws JSONException {JSONArray out=new JSONArray();for(LumaObservability.Blob b:blobs)out.put(new JSONObject().put("pixelCount",b.count).put("centroidX",b.x).put("centroidY",b.y).put("bboxInclusive",new JSONArray(new int[]{b.left,b.top,b.right,b.bottom})).put("peakY",b.peak).put("meanY",b.mean).put("touchesImageEdge",b.touchesEdge));return out;}
 private static JSONObject lumaSummary(LumaObservability.Result result)throws JSONException {JSONObject out=new JSONObject().put("sampleStep",1).put("histogram256",new JSONArray(result.histogram)).put("maxY",result.maxY).put("p50",result.p50).put("p95",result.p95).put("p99",result.p99).put("smallMaxPixels",LumaObservability.SMALL_MAX_PIXELS).put("retainedLimitPerBucket",LumaObservability.LIMIT);JSONArray levels=new JSONArray();for(LumaObservability.Threshold t:result.thresholds)levels.put(new JSONObject().put("threshold",t.threshold).put("brightPixels",t.brightPixels).put("singletonComponents",t.singletons).put("smallComponentTotal",t.smallTotal).put("largeComponentTotal",t.largeTotal).put("smallTruncated",t.smallTotal>t.small.size()).put("largeTruncated",t.largeTotal>t.large.size()).put("smallComponents",componentSummary(t.small)).put("largeComponents",componentSummary(t.large)));return out.put("levels",levels);}
 private void recordResult(TotalCaptureResult result){Long stamp=result.get(CaptureResult.SENSOR_TIMESTAMP);if(stamp!=null){matchedResults.put(stamp,result);while(matchedResults.size()>8)matchedResults.pollFirstEntry();}try{JSONObject o=new JSONObject();o.put("sensorTimestampNanos",value(result.get(CaptureResult.SENSOR_TIMESTAMP)));o.put("exposureNanos",value(result.get(CaptureResult.SENSOR_EXPOSURE_TIME)));o.put("sensitivity",value(result.get(CaptureResult.SENSOR_SENSITIVITY)));o.put("cropRegion",value(result.get(CaptureResult.SCALER_CROP_REGION)));latestResult=o;}catch(JSONException ignored){}}
 private void analyze(ImageReader r,long token){Image image=null;try{image=r.acquireLatestImage();if(image==null)return;received++;if(!live(token))return;long now=SystemClock.elapsedRealtimeNanos();if(now-startNs>=20000000000L){stop("completed-deadline");return;}if(now-lastProcessedNs<(configuredHighResolution?500000000L:200000000L)||processed>=(configuredHighResolution?40:100))return;lastProcessedNs=now;
  Image.Plane y=image.getPlanes()[0];BrightBlobDetector.Result blobs=BrightBlobDetector.analyze(y.getBuffer(),y.getRowStride(),y.getPixelStride(),image.getWidth(),image.getHeight());JSONObject o=new JSONObject();o.put("sequence",processed++);o.put("imageTimestampNanos",image.getTimestamp());long clockBefore=SystemClock.elapsedRealtimeNanos(),clockNano=System.nanoTime(),clockAfter=SystemClock.elapsedRealtimeNanos();o.put("elapsedRealtimeBeforeNanos",clockBefore);o.put("systemNanoTime",clockNano);o.put("elapsedRealtimeAfterNanos",clockAfter);o.put("rawImageMinusSystemNanoTime",image.getTimestamp()-clockNano);o.put("rawImageMinusElapsedRealtimeNanos",image.getTimestamp()-clockBefore);TotalCaptureResult observedMatch=matchedResults.get(image.getTimestamp());o.put("matchingCaptureResultAvailable",observedMatch!=null);o.put("matchedCaptureResult",observedMatch==null?JSONObject.NULL:resultSummary(observedMatch));o.put("callbackElapsedRealtimeNanos",now);o.put("elapsedMs",(now-startNs)/1000000);if(configuredHighResolution){o.put("actualTrialElapsedNanos",now-startNs);o.put("requestedActionPhase",UnmodifiedTrialPhase.phase(now-startNs));o.put("requestedActionCue",UnmodifiedTrialPhase.cue(now-startNs));o.put("physicalActionVerified",false);}o.put("brightSamples",blobs.brightSamples);o.put("totalSamples",blobs.totalSamples);o.put("captureResultLatestNotGuaranteedMatched",new JSONObject(latestResult.toString()));JSONArray list=new JSONArray();for(BrightBlobDetector.Blob b:blobs.blobs){JSONObject a=new JSONObject();a.put("sampleCount",b.count);a.put("centroidX",b.x);a.put("centroidY",b.y);list.put(a);}o.put("blobs",list);if(configuredHighResolution)o.put("lumaObservability",lumaSummary(lumaObservability.analyze(y.getBuffer(),y.getRowStride(),y.getPixelStride(),image.getWidth(),image.getHeight())));if(markerEstimator==null)matchedResults.remove(image.getTimestamp());if(markerEstimator!=null){JSONObject marker;TotalCaptureResult exact=matchedResults.remove(image.getTimestamp());try{if(exact==null)throw new IllegalArgumentException("No exact SENSOR_TIMESTAMP capture result");long imageAge=markerFrameAge(image.getTimestamp());CameraCalibration calibration=markerCalibration(exact,image.getWidth(),image.getHeight());marker=markerEstimator.analyze(y.getBuffer(),y.getRowStride(),y.getPixelStride(),image.getWidth(),image.getHeight(),calibration);markerFrameAge(image.getTimestamp());marker.put("imageAgeAtPoseStartNanos",imageAge);marker.put("matchedSensorTimestampNanos",exact.get(CaptureResult.SENSOR_TIMESTAMP));}catch(Exception e){marker=new JSONObject().put("phase","unavailable").put("reason",e.getMessage()).put("currentPose",JSONObject.NULL);}o.put("marker",marker);receipt.put("currentMarkerPose","camera-relative-marker-pose".equals(marker.optString("phase"))?marker:JSONObject.NULL);}frames.put(o);receipt.put("framesReceived",received);receipt.put("framesAnalyzed",processed);receipt.put("frames",frames);persist();String text="Frames analyzed: "+processed+"; bright components: "+list.length()+" — unclassified";if(markerEstimator!=null){JSONObject m=o.getJSONObject("marker");text="Marker "+m.optString("phase")+": "+m.optString("reason");if("camera-relative-marker-pose".equals(m.optString("phase")))text="CAMERA-relative marker t(m): "+m.getJSONArray("translationMeters")+" RMS(px): "+m.getDouble("reprojectionRmsPixels")+"; not world/Muse pose";}if(!configuredHighResolution||markerEstimator!=null)show(text);
 }catch(Exception e){if(live(token)){fail("analysis",e);stop("analysis-error");}}finally{if(image!=null)image.close();}}
 private void fail(String stage,Exception e){try{receipt.put("errorStage",stage);receipt.put("error",e.getClass().getSimpleName()+": "+String.valueOf(e.getMessage()));persist();}catch(JSONException ignored){}show(stage+": "+e.getClass().getSimpleName());}
 private void persist(){try{if(captureJournal!=null&&captureJournal.active())captureJournal.write(receipt.toString());}catch(IOException e){show("Receipt persistence failed: "+e.getClass().getSimpleName());}}
 private static int[] rect(android.graphics.Rect r){return r==null?null:new int[]{r.left,r.top,r.right,r.bottom};}
 private long markerFrameAge(long imageTimestamp){
  Integer source=captureCharacteristics.get(CameraCharacteristics.SENSOR_INFO_TIMESTAMP_SOURCE);
  return FrameFreshness.imageAge(source!=null&&source==CameraCharacteristics.SENSOR_INFO_TIMESTAMP_SOURCE_REALTIME,imageTimestamp,SystemClock.elapsedRealtimeNanos());
 }
 private CameraCalibration markerCalibration(TotalCaptureResult result,int width,int height){
  Integer distortion=result.get(CaptureResult.DISTORTION_CORRECTION_MODE),video=result.get(CaptureResult.CONTROL_VIDEO_STABILIZATION_MODE),optical=result.get(CaptureResult.LENS_OPTICAL_STABILIZATION_MODE);
  if(distortion==null||distortion!=0||video==null||video!=0||optical==null||optical!=0)throw new IllegalArgumentException("Unknown/non-OFF distortion or stabilization mode");
  if(Build.VERSION.SDK_INT>=31){Integer rotate=result.get(CaptureResult.SCALER_ROTATE_AND_CROP);if(rotate==null||rotate!=0)throw new IllegalArgumentException("Unknown/rotated image coordinates");}
  if(Build.VERSION.SDK_INT>=30){Float zoom=result.get(CaptureResult.CONTROL_ZOOM_RATIO);if(zoom==null||Math.abs(zoom-1)>1e-5)throw new IllegalArgumentException("Unknown/nonunit zoom ratio");}
  Float focus=captureCharacteristics.get(CameraCharacteristics.LENS_INFO_MINIMUM_FOCUS_DISTANCE);float[] intrinsic=result.get(CaptureResult.LENS_INTRINSIC_CALIBRATION),coefficients=result.get(CaptureResult.LENS_DISTORTION);
  if(focus!=null&&focus==0){if(intrinsic==null)intrinsic=captureCharacteristics.get(CameraCharacteristics.LENS_INTRINSIC_CALIBRATION);if(coefficients==null)coefficients=captureCharacteristics.get(CameraCharacteristics.LENS_DISTORTION);}
  return CameraCalibration.from(intrinsic,coefficients,rect(captureCharacteristics.get(CameraCharacteristics.SENSOR_INFO_PRE_CORRECTION_ACTIVE_ARRAY_SIZE)),rect(result.get(CaptureResult.SCALER_CROP_REGION)),width,height);
 }
 private void maybeQuitWorker(){if(destroying&&pendingOpens==0&&thread!=null)thread.quitSafely();}
 private void closeResources(){matchedResults.clear();if(session!=null){session.close();session=null;}if(camera!=null){camera.close();camera=null;}if(reader!=null){reader.close();reader=null;}}
 private void stop(String reason){boolean wasCapturing=capturing;capturing=false;++generation;ui.removeCallbacks(deadline);ui.removeCallbacks(trialCue);ui.removeCallbacks(poseFreshness);if(worker!=null)worker.post(()->{closeResources();if(!wasCapturing){maybeQuitWorker();return;}try{receipt.put("phase",reason);receipt.put("currentMarkerPose",JSONObject.NULL);receipt.put("framesReceived",received);receipt.put("framesAnalyzed",processed);receipt.put("stoppedWallTimeMs",System.currentTimeMillis());captureJournal.finish(receipt.toString(),"completed-deadline".equals(reason)&&processed>0);}catch(JSONException|IOException ignored){}show("Stopped: "+reason+"; frames analyzed: "+processed);maybeQuitWorker();});}
 @Override protected void onResume(){super.onResume();foreground=true;}
 @Override protected void onPause(){foreground=false;stop("backgrounded");super.onPause();}
 @Override protected void onDestroy(){destroying=true;foreground=false;stop("destroyed");super.onDestroy();}
